import re
with open(GRAPH_TTL, 'r') as f:
    content = f.read()

# Find each Room_F3_R00X Air_Temperature_Sensor and its tsref
rooms = {}
lines = content.split('\n')
for i, l in enumerate(lines):
    m = re.search(r'bldg:(Room_F3_R(\d+)\.Air_Temperature_Sensor)', l)
    if m and '.Air_Temperature_Sensor a brick:Air_Temperature_Sensor' in l:
        r = m.group(2)
        uuid = None
        for j in range(i, min(len(lines), i+12)):
            m2 = re.search(r'<urn:buildgraph:tsref:([0-9a-f\-]+)>', lines[j])
            if m2:
                uuid = m2.group(1)
                break
        rooms[r] = uuid
for r in sorted(rooms):
    print(r, rooms[r])

